SELECT json_object('section','thread','row',json_object('utid',utid,'tid',tid,'name',name,'upid',upid,'pid',pid,'process_name',process_name,'start_ts',start_ts,'end_ts',end_ts)) AS payload FROM (SELECT t.utid,t.tid,t.name,t.upid,p.pid,p.name AS process_name,t.start_ts,t.end_ts FROM thread t LEFT JOIN process p USING(upid));
CREATE PERFETTO TABLE target_states AS SELECT s.* FROM thread_state s JOIN target_threads t USING(utid) WHERE s.ts<1032251843301613 AND (s.dur<0 OR s.ts+s.dur>1032150843301613);
SELECT json_object('section','thread_state','row',json_object('id',id,'ts',ts,'dur',dur,'utid',utid,'state',state,'cpu',cpu,'waker_utid',waker_utid,'waker_id',waker_id,'irq_context',irq_context,'io_wait',io_wait,'blocked_function',blocked_function)) AS payload FROM (SELECT id,ts,dur,utid,state,cpu,waker_utid,waker_id,irq_context,io_wait,blocked_function FROM target_states ORDER BY utid,ts);
CREATE PERFETTO TABLE target_sched AS SELECT s.* FROM sched s JOIN target_threads t USING(utid) WHERE s.ts<1032251843301613 AND (s.dur<0 OR s.ts+s.dur>1032150843301613);
SELECT json_object('section','target_sched','row',json_object('id',id,'ts',ts,'dur',dur,'utid',utid,'cpu',cpu,'priority',priority,'end_state',end_state)) AS payload FROM (SELECT id,ts,dur,utid,cpu,priority,end_state FROM target_sched ORDER BY utid,ts);
CREATE PERFETTO TABLE selected_samples AS SELECT s.* FROM perf_sample s JOIN target_threads t USING(utid) WHERE EXISTS(SELECT 1 FROM selected_windows w WHERE t.tid=w.tid AND s.ts>=w.a-100000 AND s.ts<=w.b+100000);
SELECT json_object('section','perf_sample','row',json_object('id',id,'ts',ts,'utid',utid,'cpu',cpu,'cpu_mode',cpu_mode,'callsite_id',callsite_id,'unwind_error',unwind_error,'perf_session_id',perf_session_id)) AS payload FROM (SELECT id,ts,utid,cpu,cpu_mode,callsite_id,unwind_error,perf_session_id FROM selected_samples ORDER BY ts);
SELECT json_object('section','stack_callsites','row',json_object('id',id,'parent_id',parent_id,'frame_id',frame_id,'depth',depth,'name',name,'mapping_name',mapping_name,'rel_pc',rel_pc)) AS payload FROM (WITH RECURSIVE c(id,parent_id,frame_id,depth) AS (SELECT s.id,s.parent_id,s.frame_id,s.depth FROM stack_profile_callsite s WHERE s.id IN (SELECT DISTINCT callsite_id FROM selected_samples) UNION SELECT p.id,p.parent_id,p.frame_id,p.depth FROM stack_profile_callsite p JOIN c ON c.parent_id=p.id) SELECT c.id,c.parent_id,c.frame_id,c.depth,f.name,m.name AS mapping_name,f.rel_pc FROM c JOIN stack_profile_frame f ON c.frame_id=f.id LEFT JOIN stack_profile_mapping m ON f.mapping=m.id);
CREATE PERFETTO TABLE validation_samples AS SELECT s.* FROM perf_sample s JOIN target_threads t USING(utid) WHERE s.id%97=0 AND s.ts BETWEEN 1032151343301613 AND 1032251343301613;
SELECT json_object('section','stack_validation','row',json_object('id',id,'ts',ts,'utid',utid,'cpu',cpu,'perf_session_id',perf_session_id,'supported_100us',supported_100us,'supported_2us',supported_2us)) AS payload FROM (SELECT s.id,s.ts,s.utid,s.cpu,s.perf_session_id,EXISTS(SELECT 1 FROM target_sched r WHERE r.utid=s.utid AND r.cpu=s.cpu AND r.dur>=0 AND r.ts-100000<=s.ts AND r.ts+r.dur+100000>=s.ts) AS supported_100us,EXISTS(SELECT 1 FROM target_sched r WHERE r.utid=s.utid AND r.cpu=s.cpu AND r.dur>=0 AND r.ts-2000<=s.ts AND r.ts+r.dur+2000>=s.ts) AS supported_2us FROM validation_samples s);
SELECT json_object('section','wakeup','row',json_object('id',id,'ts',ts,'name',name,'waker_utid',waker_utid,'target_tid',target_tid,'target_cpu',target_cpu,'success',success)) AS payload FROM (SELECT e.id,e.ts,e.name,e.utid AS waker_utid,EXTRACT_ARG(e.arg_set_id,'pid') AS target_tid,EXTRACT_ARG(e.arg_set_id,'target_cpu') AS target_cpu,EXTRACT_ARG(e.arg_set_id,'success') AS success FROM ftrace_event e WHERE e.name IN ('sched_waking','sched_wakeup','sched_wakeup_new') AND e.ts BETWEEN 1032151343301613 AND 1032251343301613 AND EXISTS(SELECT 1 FROM selected_windows w WHERE e.ts BETWEEN w.a-100000 AND w.b+100000) AND EXTRACT_ARG(e.arg_set_id,'pid') IN (SELECT tid FROM target_threads) ORDER BY e.ts);
CREATE PERFETTO TABLE selected_runnable AS SELECT s.id AS state_id,s.ts,s.dur,s.utid,COALESCE(s.cpu,(SELECT r.cpu FROM target_sched r WHERE r.utid=s.utid AND r.ts>=s.ts ORDER BY r.ts LIMIT 1)) AS observed_resume_cpu FROM target_states s WHERE s.state IN ('R','R+') AND s.dur>0 AND EXISTS(SELECT 1 FROM selected_windows w JOIN target_threads t ON t.tid=w.tid WHERE s.utid=t.utid AND s.ts<w.b AND s.ts+s.dur>w.a);
SELECT json_object('section','cpu_competition','row',json_object('state_id',state_id,'target_utid',target_utid,'waiting_start',waiting_start,'waiting_end',waiting_end,'cpu',cpu,'sched_id',sched_id,'competing_utid',competing_utid,'priority',priority,'overlap_start',overlap_start,'overlap_end',overlap_end)) AS payload FROM (SELECT w.state_id,w.utid AS target_utid,w.ts AS waiting_start,w.ts+w.dur AS waiting_end,w.observed_resume_cpu AS cpu,r.id AS sched_id,r.utid AS competing_utid,r.priority,MAX(r.ts,w.ts) AS overlap_start,MIN(r.ts+r.dur,w.ts+w.dur) AS overlap_end FROM selected_runnable w JOIN sched r ON r.cpu=w.observed_resume_cpu AND r.ts<w.ts+w.dur AND r.ts+r.dur>w.ts WHERE r.dur>=0 AND r.utid!=w.utid);
SELECT json_object('section','window_stats','row',json_object('name',name,'idx',idx,'severity',severity,'source',source,'value',value)) AS payload FROM (SELECT name,idx,severity,source,value FROM stats WHERE value!=0 AND (severity IN ('error','data_loss') OR name GLOB '*lost*' OR name GLOB '*overrun*' OR name GLOB '*dropped*'));